export function expand(axiom, rules, n) {
  let s = axiom;
  for (let i = 0; i < n; i++) {
    s = [...s].map(ch => rules[ch] ?? ch).join('');
  }
  return s;
}

export function validateBrackets(s) {
  let depth = 0;
  for (const ch of s) {
    if (ch === '[') depth++;
    else if (ch === ']') { depth--; if (depth < 0) throw new Error('Unmatched "]"'); }
  }
  if (depth !== 0) throw new Error(`Unmatched "[": ${depth} unclosed`);
  return true;
}
```

