/**
 * Pure L-system string rewriting.
 *
 * expand("F", { F: "F[+F]F[-F]F" }, 2)
 *   -> applies the rule n times in parallel to every symbol.
 */

export function expand(axiom, rules, n) {
  let s = axiom;
  for (let i = 0; i < n; i++) {
    let next = "";
    for (const ch of s) {
      // Parallel rewrite: rewrite every symbol simultaneously from the
      // previous generation only. `rules[ch] ?? ch` handles symbols with
      // no production (they pass through unchanged).
      next += Object.prototype.hasOwnProperty.call(rules, ch) ? rules[ch] : ch;
    }
    s = next;
  }
  return s;
}

/**
 * Validate bracket balance of an L-system string.
 * Throws on mismatched "[" / "]".
 */
export function validateBrackets(s) {
  let depth = 0;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (ch === "[") depth++;
    else if (ch === "]") {
      depth--;
      if (depth < 0) {
        throw new Error(`Mismatched brackets: unmatched ']' at index ${i}`);
      }
    }
  }
  if (depth !== 0) {
    throw new Error(`Mismatched brackets: ${depth} unclosed '['`);
  }
  return true;
}

