import * as THREE from "three";
import { expand, validateBrackets } from "./lsystem.js";

const DEFAULT_RULES = { F: "F[+F]F[-F]F" };

/**
 * Grow ivy: expand the L-system and interpret it with a 3D turtle.
 *
 * Turtle alphabet:
 *   F  draw one cylinder segment, then advance `step` along the heading (+Y)
 *   +  pitch by +angleDeg about z
 *   -  pitch by -angleDeg about z
 *   [  push the turtle transform
 *   ]  pop the transform; a leaf plane caps the branch tip at pop time
 *      (pops only happen at depth > 0 by construction)
 *
 * The turtle is implemented with THREE.Matrix4 transforms; every segment is
 * baked into world space via mesh.applyMatrix4.
 *
 * @returns {THREE.Group} root group containing segment meshes and leaf meshes,
 *          with userData.segmentCount = number of F segments drawn.
 */
export function growIvy(n, { angleDeg = 22.5, step = 1, rules = DEFAULT_RULES } = {}) {
  const str = expand("F", rules, n);
  validateBrackets(str); // throws on mismatched input

  const group = new THREE.Group();
  const rad = THREE.MathUtils.degToRad(angleDeg);

  // Segment geometry: unit cylinder along +Y with its base at the origin so
  // it extends forward from the turtle position along its heading.
  const segmentGeo = new THREE.CylinderGeometry(step * 0.04, step * 0.06, step, 6);
  segmentGeo.translate(0, step / 2, 0);
  const segmentMat = new THREE.MeshStandardMaterial({ color: 0x5a4a2f });

  const leafGeo = new THREE.PlaneGeometry(step * 0.35, step * 0.35);
  leafGeo.translate(0, step * 0.175, 0); // attach at its base edge
  const leafMat = new THREE.MeshStandardMaterial({
    color: 0x77b255,
    side: THREE.DoubleSide,
  });

  let m = new THREE.Matrix4(); // identity: turtle at origin, heading +Y
  const stack = [];
  let depth = 0;
  let segmentCount = 0;

  for (const ch of str) {
    switch (ch) {
      case "F": {
        const mesh = new THREE.Mesh(segmentGeo, segmentMat);
        mesh.applyMatrix4(m); // bake current transform into world space
        group.add(mesh);
        segmentCount++;
        m = m.clone().multiply(new THREE.Matrix4().makeTranslation(0, step, 0));
        break;
      }
      case "+":
        m = m.clone().multiply(new THREE.Matrix4().makeRotationZ(rad));
        break;
      case "-":
        m = m.clone().multiply(new THREE.Matrix4().makeRotationZ(-rad));
        break;
      case "[":
        stack.push(m.clone());
        depth++;
        break;
      case "]": {
        // Branch tip: cap it with a leaf (depth > 0 guaranteed here because
        // validateBrackets ensures ']' always has a matching '[').
        if (depth <= 0) throw new Error("Turtle popped an empty stack");
        const leaf = new THREE.Mesh(leafGeo, leafMat);
        leaf.applyMatrix4(m);
        group.add(leaf);
        m = stack.pop();
        depth--;
        break;
      }
      default:
        // Unknown symbols are ignored by the turtle.
        break;
    }
  }

  group.userData.segmentCount = segmentCount;
  return group;
}

