import { describe, it, expect } from "vitest";
import * as THREE from "three";
import { expand, validateBrackets } from "../src/lsystem.js";
import { growIvy } from "../src/ivy.js";

const RULE = { F: "F[+F]F[-F]F" };

describe("expand", () => {
  it("n = 1 equals exactly F[+F]F[-F]F", () => {
    expect(expand("F", RULE, 1)).toBe("F[+F]F[-F]F");
  });

  it("n = 2 length matches the recurrence computed here", () => {
    // Recurrence: each generation replaces every F (1 char) with an 11-char
    // string, so L(k+1) = 11 * L(k), L(0) = 1 -> L(n) = 11^n.
    const L = [1];
    for (let k = 1; k <= 6; k++) L[k] = 11 * L[k - 1];

    expect(expand("F", RULE, 0)).toHaveLength(L[0]);
    expect(expand("F", RULE, 2)).toHaveLength(L[2]);
    expect(expand("F", RULE, 3)).toHaveLength(L[3]);
    expect(expand("F", RULE, 4)).toHaveLength(L[4]);
  });
});

describe("growIvy", () => {
  /** Count cylinder-segment meshes in the grown plant. */
  function countSegments(group) {
    let count = 0;
    group.traverse((obj) => {
      if (obj.isMesh && obj.geometry.type === "CylinderGeometry") count++;
    });
    return count;
  }

  it("segment mesh count equals number of F characters", () => {
    for (const n of [1, 2, 3]) {
      const str = expand("F", RULE, n);
      const fCount = [...str].filter((c) => c === "F").length;
      const group = growIvy(n);
      expect(countSegments(group)).toBe(fCount);
      expect(group.userData.segmentCount).toBe(fCount);
    }
  });

  it("bracket balance is validated (mismatched input throws)", () => {
    expect(() => validateBrackets("F[+F]F")).not.toThrow();
    expect(() => validateBrackets("F[+F]F[").toThrow()).toBeDefined?.();
    expect(() => validateBrackets("F[+F]F[")).toThrow();
    expect(() => validateBrackets("F[+F]]F")).toThrow();
    expect(() => validateBrackets("F][")).toThrow();

    // A rule that produces unbalanced brackets makes growIvy throw too.
    expect(() => growIvy(1, { rules: { F: "F[+F" } })).toThrow();
    expect(() => growIvy(1, { rules: { F: "F]" } })).toThrow();
    // The default rule is balanced, of course.
    expect(() => growIvy(3)).not.toThrow();
  });

  it("Box3 y-extent grows with n (n=2 vs n=3)", () => {
    const box2 = new THREE.Box3().setFromObject(growIvy(2));
    const box3 = new THREE.Box3().setFromObject(growIvy(3));

    const extent2 = box2.max.y - box2.min.y;
    const extent3 = box3.max.y - box3.min.y;

    expect(extent3).toBeGreaterThan(extent2);
  });

  it("same input is deterministic", () => {
    const digest = (group) => {
      const parts = [];
      group.traverse((obj) => {
        if (!obj.isMesh) return;
        const p = obj.position.toArray().map((v) => v.toFixed(8));
        const q = obj.quaternion.toArray().map((v) => v.toFixed(8));
        parts.push(`${obj.geometry.type}:${p.join(",")}:${q.join(",")}`);
      });
      return parts.sort().join("|");
    };

    expect(digest(growIvy(3))).toBe(digest(growIvy(3)));
    expect(digest(growIvy(2))).toBe(digest(growIvy(2)));

    const b1 = new THREE.Box3().setFromObject(growIvy(2));
    const b2 = new THREE.Box3().setFromObject(growIvy(2));
    expect(b1.min.equals(b2.min)).toBe(true);
    expect(b1.max.equals(b2.max)).toBe(true);
  });
});

