    expect(() => validateBrackets("F][")).toThrow();

    // A rule that produces unbalanced brackets makes growIvy throw too.
    expect(() => growIvy(1, { rules: { F: "F[+F" } })).toThrow();
    expect(() => growIvy(1, { rules: { F: "F]" } })).toThrow();
