    expect(extent3).toBeGreaterThan(extent2);
  });

  it("same input is deterministic", () => {
    const digest = (group) => {
      const parts = [];
      group.traverse((obj) => {
        if (!obj.isMesh) return;
        const p = obj.position.toArray().map((v) => v.toFixed(8));
        const q = obj.quaternion.toArray().map((v) => v.toFixed(8));
        parts.push(`${obj.geometry.type}:${p.join(",")}:${q.join(",")}`);
      });
      return parts.sort().join("|");
    };

    expect(digest(growIvy(3))).toBe(digest(growIvy(3)));
    expect(digest(growIvy(2))).toBe(digest(growIvy(2)));

    const b1 = new THREE.Box3().setFromObject(growIvy(2));
    const b2 = new THREE.Box3().setFromObject(growIvy(2));
    expect(b1.min.equals(b2.min)).toBe(true);
    expect(b1.max.equals(b2.max)).toBe(true);
  });
